<?php defined('ABSPATH')||exit;get_header();while(have_posts()):the_post();$id=get_the_ID();$status=morgenbrot_location_status($id);$days=['monday'=>'Montag','tuesday'=>'Dienstag','wednesday'=>'Mittwoch','thursday'=>'Donnerstag','friday'=>'Freitag','saturday'=>'Samstag','sunday'=>'Sonntag'];?><main id="main-content"><article class="section shell"><div class="single-grid location-single"><div><?php if(has_post_thumbnail())the_post_thumbnail('large',['alt'=>get_the_title()]);else morgenbrot_placeholder('shop');?></div><div><span class="status <?php echo esc_attr($status[0]);?>"><?php echo esc_html($status[1]);?></span><p class="eyebrow">Fiktive Filiale</p><h1><?php the_title();?></h1><div class="entry-content"><?php the_content();?></div><address><?php echo esc_html(morgenbrot_meta($id,'street'));?><br><?php echo esc_html(morgenbrot_meta($id,'postal_code').' '.morgenbrot_meta($id,'city'));?><small>Demonstrationsadresse – kein realer Betrieb.</small></address><p><a href="tel:<?php echo esc_attr(preg_replace('/[^+0-9]/','',morgenbrot_meta($id,'phone')));?>"><?php echo esc_html(morgenbrot_meta($id,'phone'));?></a><br><a href="mailto:<?php echo esc_attr(morgenbrot_meta($id,'email'));?>"><?php echo esc_html(morgenbrot_meta($id,'email'));?></a></p><h2>Öffnungszeiten</h2><ul class="hours"><?php foreach($days as$day=>$label):$hours=morgenbrot_meta($id,'hours_'.$day);?><li><strong><?php echo esc_html($label);?></strong><span><?php echo esc_html($hours?:'Geschlossen');?></span></li><?php endforeach;?></ul><h2>Services</h2><ul class="service-list"><?php if(morgenbrot_meta($id,'parking'))echo'<li>Parkplätze</li>';if(morgenbrot_meta($id,'accessible'))echo'<li>Barrierefreier Eingang</li>';foreach(array_filter(array_map('trim',explode(',',(string)morgenbrot_meta($id,'services'))))as$service)echo'<li>'.esc_html($service).'</li>';?></ul></div></div></article><div class="section shell"><?php get_template_part('template-parts/locations','map');?></div></main><?php endwhile;get_footer();
